/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic        clk,
    input  logic        reset,
    output wire  [2:0]  ena,
    output logic [15:0] q
);
    assign ena[0] = (q[3:0] == 4'd9);
    assign ena[1] = (q[7:0] == 8'h99);
    assign ena[2] = (q[11:0] == 12'h999);

    always_ff @(posedge clk) begin
        if (reset) begin
            q <= 16'h0000;
        end else begin
            q[3:0] <= (q[3:0] == 4'd9) ? 4'd0 : q[3:0] + 4'd1;
            if (ena[0])
                q[7:4] <= (q[7:4] == 4'd9) ? 4'd0 : q[7:4] + 4'd1;
            if (ena[1])
                q[11:8] <= (q[11:8] == 4'd9) ? 4'd0 : q[11:8] + 4'd1;
            if (ena[2])
                q[15:12] <= (q[15:12] == 4'd9) ? 4'd0 : q[15:12] + 4'd1;
        end
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic reset = 1;
    wire [2:0] ena;
    wire [15:0] q;
    integer expected = 0;
    integer checks = 0;
    logic [15:0] expected_q;
    logic [2:0] expected_ena;
    TopModule dut (.clk(clk), .reset(reset), .ena(ena), .q(q));
    always #5 clk = ~clk;

    task automatic check_outputs;
        begin
            expected_q[3:0] = expected % 10;
            expected_q[7:4] = (expected / 10) % 10;
            expected_q[11:8] = (expected / 100) % 10;
            expected_q[15:12] = (expected / 1000) % 10;
            expected_ena[0] = (expected % 10 == 9);
            expected_ena[1] = (expected % 100 == 99);
            expected_ena[2] = (expected % 1000 == 999);
            if (q !== expected_q || ena !== expected_ena)
                $fatal(1, "FAIL count=%0d q=%h expected=%h ena=%b expected=%b", expected, q, expected_q, ena, expected_ena);
            checks = checks + 1;
        end
    endtask

    task automatic step;
        begin
            @(posedge clk);
            if (reset) expected = 0;
            else expected = (expected + 1) % 10000;
            #1;
            check_outputs();
        end
    endtask

    initial begin
        step();
        @(negedge clk); reset = 0;
        repeat (20005) step();
        // Assert reset between edges and verify it is synchronous.
        @(negedge clk); reset = 1;
        #1; check_outputs();
        step();
        step();
        @(negedge clk); reset = 0;
        repeat (1234) step();
        @(negedge clk); reset = 1;
        #1; check_outputs();
        step();
        @(negedge clk); reset = 0;
        repeat (20) step();
        $display("PASS: %0d checks, full decimal rollover and synchronous reset", checks);
        $finish;
    end
    initial begin
        #300000;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

